"""Dependency-free management and World Model UI served by the Body host."""

BODY_GUI_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>Body Runtime · Embodied World Model</title>
<style>
:root{color-scheme:dark;font:14px Inter,ui-sans-serif,system-ui,sans-serif;background:#111613;color:#dce6df;--line:#303b33;--muted:#8e9e92;--green:#77d6a1;--cyan:#69cbd0;--panel:#171e19;--ink:#07120f}*{box-sizing:border-box}body{margin:0;min-width:320px;background:#111613}.shell{max-width:1540px;margin:0 auto;padding:28px 38px 48px}.eyebrow,.section-label{color:#76d9db;font:11px ui-monospace,monospace;letter-spacing:.08em}.topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;border-bottom:1px solid var(--line);padding-bottom:20px}.title h1{font-size:28px;font-weight:480;margin:8px 0 5px}.title p{color:var(--muted);font-size:12px;line-height:1.5;margin:0;max-width:680px}.top-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}.status-line{color:#a9c0b2;font-size:11px;margin-right:4px}button,.nav-link{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid #416b54;border-radius:4px;background:#14251b;color:#d9f5e5;padding:9px 12px;font:12px inherit;cursor:pointer;text-decoration:none}button:hover,.nav-link:hover{background:#1c3827;border-color:#70b58c}button:disabled{opacity:.45;cursor:wait}.nav{display:flex;gap:6px;margin:16px 0 22px;border-bottom:1px solid var(--line)}.nav button{background:transparent;border:0;border-bottom:2px solid transparent;color:#8fa297;padding:10px 13px;border-radius:0}.nav button.active{color:#b9f3cd;border-bottom-color:var(--green)}.view[hidden]{display:none}.stats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;margin:20px 0 14px}.stat{min-width:0;border:1px solid #304137;border-top:2px solid var(--cyan);background:#101b16;padding:12px 14px}.stat span{display:block;color:#8ca79a;font-size:10px;text-transform:uppercase}.stat b{display:block;margin-top:7px;color:#e1eee5;font:15px ui-monospace,monospace;overflow-wrap:anywhere}.goal-success{display:flex;align-items:center;gap:12px;margin:16px 0;padding:13px 16px;border:1px solid #5cb980;background:#153824;color:#d8ffe5}.goal-success[hidden]{display:none}.success-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:#69d393;color:#082015;font-size:20px;font-weight:700}.success-copy{display:grid;gap:3px}.success-copy strong{font-size:14px}.success-copy span,.success-meta{font-size:11px;color:#a8daba}.success-meta{margin-left:auto;white-space:nowrap}.panel{min-width:0;border:1px solid var(--line);background:var(--panel);padding:16px}.panel-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:0 0 11px}.panel-head h2{margin:0;color:#9cd8b3;font:11px ui-monospace,monospace;letter-spacing:.06em;text-transform:uppercase}.panel-head small,.muted{color:var(--muted);font-size:11px}.map-panel{margin-bottom:14px}.map-intro{color:var(--muted);font-size:11px;line-height:1.5;margin:0 0 12px}.map-layout{display:grid;grid-template-columns:minmax(0,1fr) 220px;gap:16px;align-items:stretch}.map-wrap{position:relative;min-height:420px;padding:12px;border:1px solid #315044;background:#07120f radial-gradient(ellipse at 50% 45%,#183a2c55,transparent 65%)}svg.map{display:block;width:100%;height:100%;min-height:390px;max-height:650px}.room{fill:#0a1915;stroke:#68a888;stroke-width:.07}.gridline{stroke:#18372d;stroke-width:.025}.goal-ring{fill:none;stroke:#e5d17b;stroke-width:.09;stroke-dasharray:.18 .1}.reach{fill:#78d6ad12;stroke:#78d6ad63;stroke-width:.035;stroke-dasharray:.1 .08}.object{fill:#9bb8aa;stroke:#07120f;stroke-width:.07}.object.target{fill:#efb17d}.object.obstacle{fill:#a17c9f}.object.mobile{fill:#d588c2}.object.table{fill:#d6c477}.object.chair{fill:#8bb2d2}.body-dot{fill:#b6f1d3;stroke:#10291f;stroke-width:.08}.heading{fill:#edfff4}.map-label{fill:#d8eee1;font: .25px ui-monospace,monospace;paint-order:stroke;stroke:#07120f;stroke-width:.055}.scene-legend{display:flex;flex-direction:column;gap:0;max-height:440px;overflow:auto;padding-right:4px}.legend-row{display:grid;grid-template-columns:27px minmax(0,1fr);gap:8px;align-items:center;border-bottom:1px solid #29382f;padding:8px 0}.legend-key{display:grid;place-items:center;width:25px;height:25px;border-radius:50%;background:#829e8e;color:#08130e;font:11px ui-monospace,monospace;font-weight:700}.legend-key.body{background:#b6f1d3}.legend-key.target{background:#efb17d}.legend-key.obstacle{background:#a17c9f}.legend-key.mobile{background:#d588c2}.legend-key.table{background:#d6c477}.legend-key.chair{background:#8bb2d2}.legend-row b{display:block;color:#cce4d5;font-size:11px;font-weight:550}.legend-row small{display:block;color:#81978a;font-size:10px;margin-top:2px}.legend-foot{margin-top:auto;padding-top:10px;color:#779386;font-size:10px;line-height:1.5}.truth-note{margin-top:10px;border-left:2px solid #47775a;padding:5px 0 5px 10px;color:#8da99a;font-size:10px;line-height:1.45}.truth-note b{display:block;color:#b6d0c0;margin-bottom:3px}.detail-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}.detail-block+.detail-block{margin-top:20px}.meta{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:10px}.meta span{padding:5px 7px;border:1px solid #30443b;color:#8ea89a;font-size:10px}.meta b{color:#cce4d5;font-weight:500}.perception-text{margin:0;color:#bfcec4;font-size:12px;line-height:1.6}.object-list,.event-list{max-height:260px;overflow:auto}.row{display:flex;justify-content:space-between;align-items:center;gap:14px;border-top:1px solid #29382f;padding:9px 1px;color:#c6d8cc;font-size:11px}.row small{display:block;color:#83988b;margin-top:3px}.row strong{font:11px ui-monospace,monospace;color:#b9d9c7;white-space:nowrap}.json{margin:0;max-height:260px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:#081019;color:#a8d9c2;padding:12px;border:1px solid #233a31;font:10px/1.5 ui-monospace,monospace}.world-layout{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.wide{grid-column:1/-1}.plugin-list{display:grid;gap:6px}.plugin{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid #29382f;padding:10px 2px}.plugin-info{display:grid;grid-template-columns:10px minmax(0,1fr);gap:8px;align-items:center}.dot{width:8px;height:8px;border-radius:50%;background:#68776d}.dot.on{background:#76e0a6;box-shadow:0 0 0 3px #76e0a622}.plugin-info b{font-size:12px;font-weight:550}.plugin-info small{grid-column:2;color:#82978b;font-size:10px}.plugin input{width:18px;height:18px;accent-color:#76d6a1}.plugin-settings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:16px;padding-top:15px;border-top:1px solid var(--line)}.plugin-settings[hidden]{display:none}.field{display:grid;gap:6px;color:#91a99a;font-size:10px}.field input{min-width:0;width:100%;border:1px solid #3a4a3e;border-radius:4px;background:#101914;color:#dce8df;padding:9px;font:11px ui-monospace,monospace}.field.wide{grid-column:1/-1}.field.check{display:flex;align-items:center;gap:8px}.field.check input{width:16px;height:16px}.plugin-actions{display:flex;gap:8px;margin-top:12px}.map-modal{position:fixed;inset:0;z-index:10;display:none;place-items:center;background:#020806ee;padding:24px}.map-modal.open{display:grid}.modal-inner{width:min(96vw,1450px);height:min(94vh,1050px);display:flex;flex-direction:column;border:1px solid #4c896b;background:#0b1812;padding:16px}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.modal-head h2{font:11px ui-monospace,monospace;color:#9cd8b3}.modal-layout{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:16px;flex:1;min-height:0}.modal-layout svg{min-height:0;max-height:none}.modal-close{font-size:19px;padding:5px 10px}.message{min-height:16px;color:#a7bcae;font-size:11px}.goal-achieved-page .goal-success{margin-top:18px}@media(max-width:900px){.shell{padding:22px 20px}.stats{grid-template-columns:repeat(3,minmax(0,1fr))}.map-layout{grid-template-columns:minmax(0,1fr) 190px}.map-wrap{min-height:340px}.detail-grid,.world-layout{grid-template-columns:1fr}}@media(max-width:620px){.shell{padding:18px 13px 32px}.topbar{display:block}.top-actions{justify-content:flex-start;margin-top:14px}.stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.stat{padding:10px}.stat b{font-size:13px}.map-layout,.modal-layout{grid-template-columns:1fr}.map-wrap{min-height:290px;padding:7px}svg.map{min-height:270px}.scene-legend{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;max-height:230px}.legend-foot{grid-column:1/-1}.success-meta{display:none}.panel{padding:13px}.plugin-settings{grid-template-columns:1fr}.field.wide{grid-column:auto}.map-modal{padding:8px}.modal-inner{width:98vw;height:96vh;padding:10px}.modal-layout{overflow:auto}.modal-layout svg{min-height:50vh}}
</style>
</head>
<body>
<main class="shell">
<header class="topbar"><div class="title"><div class="eyebrow">COGNITIVE ORGANISM / BODY</div><h1 id="page-title">Independent Body Runtime</h1><p id="page-description">The Body owns perception, plugins, physical memory and action. The Brain consumes its observations through the connector.</p></div><div class="top-actions"><span id="message" class="status-line">Connecting to Body…</span><button id="run-toggle" onclick="toggleSimulation()">Start simulation</button><button onclick="step()">Step once</button><button onclick="resetModel()">Reset simulation</button><button onclick="refreshAll()" aria-label="Refresh">Refresh</button></div></header>
<nav class="nav"><button id="nav-body" onclick="showView('body')">Body &amp; plugins</button><button id="nav-world" onclick="showView('worldmodel')">Embodied World Model</button></nav>
<section id="view-body" class="view" hidden><div class="stats"><div class="stat"><span>Runtime</span><b id="runtime">—</b></div><div class="stat"><span>Plugins</span><b id="plugin-count">—</b></div><div class="stat"><span>Observations</span><b id="observation-count">—</b></div><div class="stat"><span>World model</span><b id="mode">—</b></div><div class="stat"><span>Source</span><b id="source">—</b></div><div class="stat"><span>Steps</span><b id="steps">—</b></div></div><section class="panel"><div class="panel-head"><h2>Plugins exposed to the Brain</h2><small>Configuration remains owned by the Body.</small></div><div id="plugins" class="plugin-list muted">Loading plugins…</div><div id="home-assistant-settings" class="plugin-settings" hidden><label class="field">Home Assistant URL<input id="ha-url" type="url" placeholder="http://homeassistant:8123"></label><label class="field">Long-lived access token<input id="ha-token" type="password" placeholder="Leave blank to keep current token"></label><label class="field">Polling interval (seconds)<input id="ha-poll" type="number" min="1" step="1"></label><label class="field">Allowed domains<input id="ha-domains" placeholder="Empty means all domains"></label><label class="field wide">Entities presented to the Brain<input id="ha-entities" placeholder="Comma-separated entity IDs"></label><label class="field check"><input id="ha-verify" type="checkbox"> Verify HTTPS certificate</label><div class="plugin-actions"><button onclick="saveHomeAssistantSettings()">Save settings</button><button onclick="discoverHomeAssistant()">Discover entities</button></div></div></section><section class="panel" style="margin-top:14px"><div class="panel-head"><h2>Latest Body observations</h2><small>Timestamped input stream</small></div><div id="observations" class="event-list muted">Waiting for Body observations.</div></section></section>
<section id="view-worldmodel" class="view" hidden><div id="goal-success" class="goal-success" role="status" hidden><div class="success-mark">✓</div><div class="success-copy"><strong>Goal achieved</strong><span id="success-description">Full task completed.</span></div><small id="success-meta" class="success-meta"></small></div><div class="stats"><div class="stat"><span>Mode</span><b id="wm-mode">—</b></div><div class="stat"><span>Source</span><b id="wm-source">—</b></div><div class="stat"><span>Stage</span><b id="wm-stage">—</b></div><div class="stat"><span>Steps</span><b id="wm-steps">—</b></div><div class="stat"><span>Runtime</span><b id="wm-running">—</b></div><div class="stat"><span>Prediction error</span><b id="wm-error">—</b></div></div><section class="panel map-panel"><div class="panel-head"><h2>Perception observatory</h2><button onclick="expandMap()">Expand map</button></div><p class="map-intro">Live Body position, orientation, objects, obstacles and current objective. This is the observation frame used by the Body’s world model.</p><div class="map-layout"><div class="map-wrap"><svg id="map" class="map" viewBox="0 0 12 12" role="img" aria-label="Live Body perception map"></svg></div><div id="map-legend" class="scene-legend"><span class="muted">Waiting for scene.</span></div></div><div class="truth-note"><b>Perception boundary</b><span id="truth-note">Lumina receives the observation and affordances shown here.</span></div></section><div class="detail-grid"><section class="panel"><div class="panel-head"><h2>Body’s interpreted perception</h2><small id="perception-age">No observation</small></div><div class="meta"><span>Source <b id="perception-source">—</b></span><span>Objects <b id="perception-objects-count">—</b></span></div><p id="perception-text" class="perception-text">Waiting for the first Body observation.</p><div id="object-list" class="object-list" style="margin-top:12px"></div><div class="detail-block"><div class="panel-head"><h2>Affordances</h2></div><pre id="affordances" class="json">No affordances inferred yet.</pre></div></section><section class="panel"><div class="panel-head"><h2>Physical memory</h2><small id="anchor-count">—</small></div><pre id="memory" class="json">Loading physical memory…</pre><div class="detail-block"><div class="panel-head"><h2>Learned embodied concepts</h2></div><div id="concepts" class="event-list muted">No concepts consolidated yet.</div></div></section><section class="panel"><div class="panel-head"><h2>Last policy decision</h2></div><pre id="decision" class="json">No decision recorded.</pre></section><section class="panel"><div class="panel-head"><h2>Recent sensorimotor episodes</h2><small>Newest first</small></div><div id="episodes" class="event-list muted">No episodes recorded yet.</div></section></div></section>
<div id="message-bottom" class="message" aria-live="polite"></div>
</main>
<div id="map-modal" class="map-modal" role="dialog" aria-modal="true" aria-label="Expanded Body world map"><div class="modal-inner"><div class="modal-head"><h2>Body spatial perception</h2><button class="modal-close" onclick="closeMap()" aria-label="Close map">×</button></div><div class="modal-layout"><svg id="map-large" class="map" viewBox="0 0 12 12" aria-label="Expanded perception map"></svg><div id="map-legend-large" class="scene-legend"></div></div></div></div>
<script>
const $=id=>document.getElementById(id);let currentView='body',lastStatus=null;
async function get(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw Error(path+' '+r.status);return r.json()}
async function post(path,payload={}){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error(path+' '+r.status);return r.json()}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function showView(view){currentView=view;$('view-body').hidden=view!=='body';$('view-worldmodel').hidden=view!=='worldmodel';$('nav-body').classList.toggle('active',view==='body');$('nav-world').classList.toggle('active',view==='worldmodel');$('page-title').textContent=view==='worldmodel'?'Embodied World Model':'Independent Body Runtime';$('page-description').textContent=view==='worldmodel'?'Live perception, physical memory, learned dynamics and action policy. The Body owns this model; the Brain reads it.':'The Body owns perception, plugins, physical memory and action. The Brain consumes its observations through the connector.';document.title=view==='worldmodel'?'Embodied World Model · Body':'Body Runtime';history.replaceState(null,'',view==='worldmodel'?'/worldmodel':'/');if(view==='worldmodel')void refreshWorld();else void refreshBody()}
function renderMap(w){const p=w?.perception||{},sim=w?.sim||{},objects=Array.isArray(p.objects)?p.objects:[],width=Number(sim.width||12),height=Number(sim.height||12),body=p.body?.position||sim.body||[0,0,0],shelf=sim.shelf||[1,9];const color=k=>k==='target'?'target':k==='obstacle'?'obstacle':k==='mobile_obstacle'?'mobile':k==='table'?'table':k==='chair'?'chair':'object';function draw(svg,legend){if(!svg)return;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const sy=y=>height-(Number(y)||0),sx=x=>Math.max(.25,Math.min(width-.25,Number(x)||0));let parts=[`<rect class="room" x="0" y="0" width="${width}" height="${height}"/>`];for(let i=0;i<=width;i++)parts.push(`<line class="gridline" x1="${i}" y1="0" x2="${i}" y2="${height}"/>`);for(let i=0;i<=height;i++)parts.push(`<line class="gridline" x1="0" y1="${i}" x2="${width}" y2="${i}"/>`);parts.push(`<circle class="goal-ring" cx="${sx(shelf[0])}" cy="${sy(shelf[1])}" r=".34"/><text class="map-label" x="${sx(shelf[0])+.42}" y="${sy(shelf[1])+.1}">goal</text>`);const items=[{code:'B',cls:'body',label:'Body',detail:`(${Number(body[0]).toFixed(1)}, ${Number(body[1]).toFixed(1)})`}];const reach=Number(p.body?.capabilities?.reach||1.8);parts.push(`<circle class="reach" cx="${sx(body[0])}" cy="${sy(body[1])}" r="${reach}"/>`);objects.forEach((o,i)=>{const q=o.position||[0,0],c=color(o.kind),r=Math.max(.22,Math.min(.56,Number(o.size||.4)/2));parts.push(`<circle class="object ${c}" cx="${sx(q[0])}" cy="${sy(q[1])}" r="${r}"/><text class="map-label" x="${sx(q[0])}" y="${sy(q[1])}">${i+1}</text>`);items.push({code:String(i+1),cls:c,label:o.label||o.kind,detail:`${o.kind} · (${Number(q[0]).toFixed(1)}, ${Number(q[1]).toFixed(1)})`})});parts.push(`<g transform="translate(${sx(body[0])} ${sy(body[1])}) rotate(${-Number(p.body?.orientation||0)*180/Math.PI})"><circle class="body-dot" r=".34"/><path class="heading" d="M0 0 L.72 -.19 L.72 .19 Z"/></g>`);svg.innerHTML=parts.join('');if(legend)legend.innerHTML=[...items,{code:'G',cls:'goal',label:'Goal',detail:`(${shelf[0]}, ${shelf[1]})`}].map(i=>`<div class="legend-row"><i class="legend-key ${i.cls}">${esc(i.code)}</i><span><b>${esc(i.label)}</b><small>${esc(i.detail)}</small></span></div>`).join('')+`<div class="legend-foot">${p.available?`Observation ${Number(p.age_seconds||0).toFixed(1)}s old · ${objects.length} objects`:'No observation yet'}</div>`}draw($('map'),$('map-legend'));draw($('map-large'),$('map-legend-large'));$('truth-note').textContent=p.ground_truth_available?'Simulator source: the exact scene is shown for debugging; the policy receives the observation and affordances.':'No simulator ground truth is exposed for this source.'}
function renderWorld(w){lastStatus=w;const sim=w.sim||{},p=w.perception||{},goal=w.goal_status||{};$('wm-mode').textContent=w.mode||'—';$('wm-source').textContent=w.source?.source||'—';$('wm-stage').textContent=String(sim.task_stage||'—').replaceAll('_',' ');$('wm-steps').textContent=w.steps??0;$('wm-running').textContent=w.running?'Running':'Paused';$('wm-error').textContent=w.prediction_error_ema??'—';const achieved=Boolean(goal.achieved||sim.done);$('goal-success').hidden=!achieved;if(achieved){$('success-description').textContent='Cup delivered through table placement, re-grasp, and final objective.';$('success-meta').textContent=`${goal.steps??sim.steps??0} steps · ${goal.successes??sim.successes??0} completed actions`}$('perception-age').textContent=p.available?`${Number(p.age_seconds||0).toFixed(1)}s old`:'No observation';$('perception-source').textContent=p.source||'—';$('perception-objects-count').textContent=p.objects?.length??0;$('perception-text').textContent=p.text||'Waiting for the first Body observation.';$('object-list').innerHTML=(p.objects||[]).map(o=>`<div class="row"><span><b>${esc(o.label)}</b><small>${esc(o.kind)} · ${(o.position||[]).slice(0,2).map(n=>Number(n).toFixed(1)).join(', ')}</small></span><strong>${Number(o.mass||0)} kg</strong></div>`).join('');$('affordances').textContent=p.affordances?JSON.stringify(p.affordances,null,2):'No affordances inferred yet.';const mem=w.memory||{};$('anchor-count').textContent=`${mem.lieux?.count||0} places · ${mem.objets?.count||0} objects`;$('concepts').innerHTML=(w.concepts?.top||[]).map(c=>`<div class="row"><span><b>${esc(c.label)}</b><small>${c.observations} observations · confidence ${c.confidence}</small></span><strong>${c.positive}/${c.negative}</strong></div>`).join('')||'<span class="muted">No concepts consolidated yet.</span>';$('decision').textContent=w.last_decision?JSON.stringify(w.last_decision,null,2):'No decision recorded.';const b=$('run-toggle');b.textContent=w.running?'Pause simulation':'Start simulation';b.dataset.running=String(Boolean(w.running));renderMap(w)}
async function refreshWorld(){try{const w=await get('/worldmodel/status');renderWorld(w);$('message').textContent=w.goal_status?.achieved?'Goal achieved':'Body connected'}catch(e){$('message').textContent='World model unavailable: '+e.message}}
async function refreshBody(){try{const h=await get('/health'),w=h.worldmodel||{};$('runtime').textContent=h.runtime||'—';$('plugin-count').textContent=`${(h.plugins||[]).filter(p=>p.enabled).length}/${(h.plugins||[]).length}`;$('observation-count').textContent=h.observations??0;$('mode').textContent=w.mode||'—';$('source').textContent=w.source?.source||'—';$('steps').textContent=w.steps??0;$('plugins').innerHTML=(h.plugins||[]).map(p=>`<label class="plugin"><span class="plugin-info"><i class="dot ${p.enabled?'on':''}"></i><b>${esc(p.label||p.id)}</b><small>${esc(p.role||'')}</small></span><input type="checkbox" ${p.enabled?'checked':''} onchange="togglePlugin('${esc(p.id)}',this.checked)"/></label>`).join('')||'<span class="muted">No plugins registered.</span>';const enabled=(h.plugins||[]).some(p=>p.id==='home_assistant'&&p.enabled);$('home-assistant-settings').hidden=!enabled;if(enabled&&!$('home-assistant-settings').dataset.loaded){await loadHomeAssistantSettings();$('home-assistant-settings').dataset.loaded='1'}const obs=await get('/observations');$('observations').innerHTML=(obs.observations||[]).slice(0,16).map(o=>`<div class="row"><span><b>${esc(o.subject)}</b><small>${esc(o.source)}${o.observed_at?' · '+new Date(o.observed_at*1000).toLocaleTimeString():''}</small></span><strong>${esc(o.value)}${o.unit?' '+esc(o.unit):''}</strong></div>`).join('')||'<span class="muted">No Body observations yet.</span>';$('message').textContent='Body connected'}catch(e){$('message').textContent='Body unavailable: '+e.message}}
async function refreshAll(){await(currentView==='worldmodel'?refreshWorld():refreshBody())}
async function toggleSimulation(){const running=$('run-toggle').dataset.running!=='true';try{await post('/worldmodel/run',{running,shuffle:running});await refreshWorld()}catch(e){$('message').textContent=e.message}}
async function step(){try{await post('/worldmodel/step');await refreshWorld()}catch(e){$('message').textContent=e.message}}
async function resetModel(){if(!confirm('Reset the simulation state?'))return;try{await post('/worldmodel/reset',{clear_memory:false});await refreshWorld()}catch(e){$('message').textContent=e.message}}
function expandMap(){$('map-modal').classList.add('open');document.body.style.overflow='hidden'}function closeMap(){$('map-modal').classList.remove('open');document.body.style.overflow=''}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMap()});
async function togglePlugin(id,enabled){try{await post('/plugins/'+id,{enabled});await refreshBody()}catch(e){$('message').textContent='Plugin update failed: '+e.message}}
async function loadHomeAssistantSettings(){try{const s=await get('/plugins/home_assistant/settings');$('ha-url').value=s.url||'';$('ha-poll').value=s.poll_interval||5;$('ha-domains').value=s.allowed_domains||'';$('ha-entities').value=s.entities||'';$('ha-verify').checked=!!s.verify_ssl;$('ha-token').placeholder=s.token_configured?'Token configured; leave blank to keep it':'Enter a Home Assistant token'}catch(e){$('message').textContent='Home Assistant settings unavailable: '+e.message}}
async function saveHomeAssistantSettings(){const payload={url:$('ha-url').value,token:$('ha-token').value,poll_interval:Number($('ha-poll').value||5),allowed_domains:$('ha-domains').value,entities:$('ha-entities').value,verify_ssl:$('ha-verify').checked};try{await post('/plugins/home_assistant/settings',payload);$('ha-token').value='';$('message').textContent='Home Assistant settings saved';await refreshBody()}catch(e){$('message').textContent='Home Assistant settings failed: '+e.message}}
async function discoverHomeAssistant(){try{const r=await post('/plugins/home_assistant/discover');$('message').textContent=r.ok?'Home Assistant discovery complete':(r.message||'Discovery failed');await refreshBody()}catch(e){$('message').textContent='Discovery failed: '+e.message}}
let pollTimer;async function poll(){await refreshAll();pollTimer=setTimeout(poll,currentView==='worldmodel'?900:3000)}
showView(location.pathname==='/worldmodel'?'worldmodel':'body');void poll();setInterval(()=>{if(currentView==='worldmodel')void refreshDetails()},4000);
async function refreshDetails(){try{const [a,e]=await Promise.all([get('/worldmodel/anchors'),get('/worldmodel/episodes?limit=12')]);$('memory').textContent=JSON.stringify(a,null,2);const steps=Array.isArray(e)?e:[];$('episodes').innerHTML=steps.slice().reverse().map(x=>`<div class="row"><span><b>${esc(x.action)}</b><small>step ${x.step} · reward ${x.reward} · error ${x.pred_error}</small></span><strong>${esc(x.outcome)}</strong></div>`).join('')||'<span class="muted">No episodes recorded yet.</span>'}catch{}}
</script></body></html>'''
